{
  "document_type": "lease",
  "lessor": "Shijidazhi Real Estate Consulting Service Department of Fanyu District of Guangzhou",
  "lessee": "Shanghai Mecox Lane International Mailorder Co., Ltd.",
  "premises_address": "Warehouse of Wugucao Ferry, South Shigang Road, East Shigang Village, Shiji Town, Fanyu District, Guangzhou",
  "area": null,
  "start_date": "2010-05-10",
  "end_date": "2012-05-09",
  "rent": {
    "amount": 48000,
    "currency": "CNY",
    "period": "month"
  },
  "indexation": "none",
  "red_flags": [
    {
      "type": "sublease_permitted",
      "quote": "Party B may sublet part or the whole of the Premises to another party during the tenancy (subject to the consent of Party A)."
    },
    {
      "type": "tenant_break_option",
      "quote": "Party B shall have the priority to renew the lease during the term between May 9, 2012 and May 8, 2015."
    },
    {
      "type": "tenant_break_option",
      "quote": "If Party B fails to return the Premises punctually without the consent of Party A, it shall pay double of the rent to Party A during the period of occupation of the Premises."
    },
    {
      "type": "tenant_break_option",
      "quote": "Party B may terminate the tenancy at its sole decision and/or require Party A to cover the losses suffered by it, and such termination shall not be regarded as breach of this Contract."
    },
    {
      "type": "landlord_repairs",
      "quote": "In the event that Party B discovers any damage or breakdown of the Premises and accessory facilities, it shall notify Party A promptly for reparation. Party A shall repair them within 2 days from the date of receipt of the notice."
    },
    {
      "type": "landlord_repairs",
      "quote": "Party A shall be liable to compensate Party B for its losses occasioned by Party A’s failure to inform Party B that the Premises have been mortgaged or the transfer of the ownership of the Premises has been restricted before the leasing of the Premises."
    },
    {
      "type": "landlord_repairs",
      "quote": "Party A shall be liable to compensate Party B for its property damage or personal injury occasioned by Party’s failure to perform its obligations as contained herein related to the reparation and maintenance of the Premises during the tenancy, which causes damage to the Premises."
    },
    {
      "type": "tenant_break_option",
      "quote": "In the event that Party B early surrenders the lease other than in accordance with the provisions herein during the tenancy, the Deposit paid by Party B shall not be returned."
    }
  ]
}
